# The original curated list omitted five complete Civil Code chapter/section ranges.
# Keep the verified supplement separate so the source can be audited and updated without
# rewriting the large historical dataset in this module.
LAW_CHUNKS.extend(CIVIL_CODE_SUPPLEMENT)
LAW_CHUNKS.extend(CORE_INTERPRETATION_RECORDS)
LAW_CHUNKS.extend(ADDITIONAL_STATUTE_RECORDS)
LAW_CHUNKS.extend(TECHNOLOGY_INTERPRETATION_RECORDS)


def get_all_chunks():
    return LAW_CHUNKS
